<?php declare(strict_types=1);namespace NpmGateway\Repositories;use mysqli;
final class SupplyOrderRepository{public function __construct(private readonly mysqli$db){}
 public function insert(array$r):void{$s=$this->db->prepare('INSERT INTO supply_orders(public_id,property_id,submitted_by_user_id,request_html,request_text,submitted_at)VALUES(?,?,?,?,?,?)');$s->bind_param('siisss',$r['public_id'],$r['property_id'],$r['actor_id'],$r['request_html'],$r['request_text'],$r['submitted_at']);$s->execute();$s->close();}
 public function list(int$propertyId):array{$s=$this->db->prepare("SELECT o.public_id,o.request_html,o.submitted_at,CONCAT(e.first_name,' ',e.last_name) submitted_by_name FROM supply_orders o JOIN users u ON u.id=o.submitted_by_user_id JOIN employees e ON e.id=u.employee_id WHERE o.property_id=? ORDER BY o.submitted_at DESC,o.id DESC");$s->bind_param('i',$propertyId);$s->execute();$r=$s->get_result()->fetch_all(MYSQLI_ASSOC);$s->close();return$r;}
 public function detail(string$public,int$propertyId):?array{$s=$this->db->prepare("SELECT o.public_id,o.request_html,o.request_text,o.submitted_at,p.public_id property_public_id,p.slug property_slug,p.display_name property_name,CONCAT(e.first_name,' ',e.last_name) submitted_by_name FROM supply_orders o JOIN properties p ON p.id=o.property_id JOIN users u ON u.id=o.submitted_by_user_id JOIN employees e ON e.id=u.employee_id WHERE o.public_id=? AND o.property_id=? AND p.status='active' AND p.property_code<>'CO' LIMIT 1");$s->bind_param('si',$public,$propertyId);$s->execute();$r=$s->get_result()->fetch_assoc();$s->close();return is_array($r)?$r:null;}
}
